def solve(path):
    # split by '/', ignore empty and '.'
    parts = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if parts:
                parts.pop()
            # else stay at root
        else:
            parts.append(part)
    return '/' + '/'.join(parts)

